```json
{
  "name": "OSINT Domain Intelligence Pipeline",
  "nodes": [
    {
      "parameters": {
        "rule": {
          "interval": ["0 8 * * *"]
        }
      },
      "name": "Daily 8AM Trigger",
      "type": "n8n-nodes-base.scheduleTrigger",
      "position": [0, 0]
    },
    {
      "parameters": {
        "url": "https://api.shodan.io/dns/domain/{{ $json.domain }}",
        "queryParameters": {
          "parameters": [
            {"name": "key", "value": "{{ $env.SHODAN_API_KEY }}"}
          ]
        }
      },
      "name": "Shodan DNS Lookup",
      "type": "n8n-nodes-base.httpRequest",
      "position": [250, 0]
    },
    {
      "parameters": {
        "url": "https://www.virustotal.com/api/v3/domains/{{ $json.domain }}",
        "headerParameters": {
          "parameters": [
            {"name": "x-apikey", "value": "{{ $env.VT_API_KEY }}"}
          ]
        }
      },
      "name": "VirusTotal Enrichment",
      "type": "n8n-nodes-base.httpRequest",
      "position": [500, 0]
    },
    {
      "parameters": {
        "conditions": {
          "number": [{
            "value1": "={{ $json.data.attributes.last_analysis_stats.malicious }}",
            "operation": "larger",
            "value2": 0
          }]
        }
      },
      "name": "Is Malicious?",
      "type": "n8n-nodes-base.if",
      "position": [750, 0]
    },
    {
      "parameters": {
        "channel": "osint-alerts",
        "text": "🔴 Malicious domain detected: {{ $json.domain }}\nMalicious hits: {{ $json.data.attributes.last_analysis_stats.malicious }}"
      },
      "name": "Alert Slack",
      "type": "n8n-nodes-base.slack",
      "position": [1000, -100]
    },
    {
      "parameters": {
        "operation": "insert",
        "collection": "domain_intel",
        "fields": {
          "domain": "={{ $json.domain }}",
          "vt_score": "={{ $json.data.attributes.last_analysis_stats.malicious }}",
          "timestamp": "={{ $now }}"
        }
      },
      "name": "Store Results",
      "type": "n8n-nodes-base.mongoDb",
      "position": [1000, 100]
    }
  ],
  "connections": {
    "Daily 8AM Trigger": {"main": [[{"node": "Shodan DNS Lookup"}]]},
    "Shodan DNS Lookup": {"main": [[{"node": "VirusTotal Enrichment"}]]},
    "VirusTotal Enrichment": {"main": [[{"node": "Is Malicious?"}]]},
    "Is Malicious?": {
      "main": [
        [{"node": "Alert Slack"}],
        [{"node": "Store Results"}]
      ]
    }
  }
}
```
This workflow triggers daily, queries Shodan and VirusTotal, checks if domains are flagged as malicious, alerts via Slack, and stores all results.
